        [1106] = {"暗影箭", "向敌人发射暗影箭，造成 142 到 163 点暗影伤害。", "SpellTranslation", "等级 5"},
        [1108] = {"虚弱诅咒", "使目标近战攻击强度降低 41 点，持续 2分钟。同一术士对同一目标只能激活一个诅咒。\n\n效果：近战攻击强度降低 41 点。", "SpellTranslation", "等级 2"},
        [1120] = {"吸取灵魂", "吸取目标的灵魂，在 15秒内造成 135 点暗影伤害；根据目标已损失生命值，伤害最多提高 40%。如果目标在引导期间死亡且可提供经验值或荣誉，施法者获得一块灵魂碎片。\n\n效果：每 1 秒造成 9 点暗影伤害。", "SpellTranslation", "等级 1"},
        [1121] = {"Entangle", "被定身。", "SpellTranslation"},
        [1122] = {"地狱火", "从扭曲虚空召唤陨石，对区域内所有敌方目标造成火焰伤害并使其昏迷。一个地狱火从陨坑中升起，在施法者命令下作战 5 分钟。", "SpellTranslation", "召唤"},
        [1126] = {"野性印记", "使友方目标的护甲提高 25 点，持续 30分钟。\n\n效果：护甲提高 25。点。", "SpellTranslation", "等级 1"},
        [1130] = {"猎人印记", "在目标身上施加猎人印记，使所有攻击者对该目标的远程攻击强度提高 20 点。每次被远程攻击命中后，远程攻击强度额外提高 2 点，最高 80 点。此外，猎人始终可以看见该目标，即使目标潜行或隐形；目标也会显示在小地图上。持续 5 分钟。\n\n效果：所有攻击者对该目标的远程攻击强度提高 20 点，每次远程攻击命中后额外提高 2 点，最高 80 点。", "SpellTranslation", "等级 1"},
        [1152] = {"纯净术", "净化友方目标，移除 1 个疾病效果和 1 个中毒效果。", "SpellTranslation"},
        [1159] = {"急救", "每 1 秒恢复 250 点生命值。", "SpellTranslation"},
        [1160] = {"挫志怒吼", "使10码范围内的所有敌人的近战攻击强度降低35点，持续30秒。\n\n效果：近战攻击强度降低 35 点。", "SpellTranslation", "等级 1"},
