        [1462] = {"野兽知识", "收集目标野兽的信息，显示其伤害、生命值、护甲和抗性，以及饮食偏好。\n\n效果：已显示野兽信息。", "SpellTranslation"},
        [1463] = {"法力护盾", "吸收 120 点伤害，改为消耗法力值。每吸收 1 点伤害消耗 1 点法力值，持续 1 分钟。\n\n效果：吸收伤害，改为消耗法力值。", "SpellTranslation", "等级 1"},
        [1464] = {"猛击", "猛击对手，造成武器伤害加上32点额外伤害。", "SpellTranslation", "等级 1"},
        [1490] = {"元素诅咒", "诅咒目标 5分钟，使其奥术、火焰、冰霜、自然和暗影抗性降低 45 点，并使其受到的魔法伤害提高 6%。同一术士对同一目标只能激活一个诅咒。\n\n效果：奥术、火焰、冰霜、自然和暗影抗性降低 45 点，受到的魔法伤害提高 6%。", "SpellTranslation", "等级 1"},
