        [1495] = {"猫鼬撕咬", "反击敌人，造成 25 点加攻击强度 20% 的伤害。只能在你躲闪后使用。", "SpellTranslation", "等级 1"},
        [1499] = {"冰冻陷阱", "放置冰霜陷阱，冻结第一个靠近的敌人，使其无法行动，最多持续 10秒。任何伤害都会打破冰冻。陷阱存在 1 分钟。同一时间只能激活一个陷阱。", "SpellTranslation", "等级 1"},
        [1510] = {"乱射", "向目标区域持续射出大量弹药，持续 6 秒，每秒对 8 码范围内的敌方目标造成 50 点奥术伤害。", "SpellTranslation", "等级 1"},
        [1513] = {"恐吓野兽", "恐吓一只野兽，使其因恐惧逃跑，最多持续 20秒。伤害可能打断该效果。同一时间只能恐吓一只野兽。\n\n效果：被恐惧。", "SpellTranslation", "等级 1"},
        [1515] = {"驯服野兽", "开始驯服一只野兽作为你的伙伴。在 20 秒驯服期间，你的护甲值降低 100%。如果你失去野兽的注意力，驯服会失败。\n\n效果：正在驯服宠物。", "SpellTranslation"},
        [1535] = {"火焰新星图腾", "召唤一个拥有 5 点生命值的火焰新星图腾，持续 5秒。若图腾在 4 秒内没有被摧毁，则对 10 码范围内的敌人造成 48 点火焰伤害。", "SpellTranslation", "等级 1"},
        [1543] = {"照明弹", "照亮目标区域，使 10 码范围内所有潜行和隐形的敌人显形，持续 20 秒。\n\n效果：潜行和隐形单位会被显形。", "SpellTranslation"},
