        [11069] = {"强化火球术", "使你的火球术施法时间缩短 0.1 秒。\n\n效果：减少火球术施法时间 0.1 秒。", "SpellTranslation", "等级 1"},
        [11070] = {"强化寒冰箭", "使你的寒冰箭施法时间缩短 0.1 秒。\n\n效果：减少冰箭法术的施法时间 0.1 秒。", "SpellTranslation", "等级 1"},
        [11071] = {"霜寒刺骨", "你的寒冷效果有 5% 几率将目标冻结 5 秒。如果目标免疫冻结，则会被视为被冻结。\n\n效果：让你的冰冷效果有 5% 的几率将目标冻结在原地 5 秒。如果目标免疫被冻结，则该目标将被视为被冻结。", "SpellTranslation", "等级 1"},
        [11078] = {"强化冲击", "强化冲击。\n\n效果：减少你的火焰冲击法术的冷却时间 0.5 秒，并增加你的奥术冲击法术的暴击几率 1%。", "SpellTranslation", "等级 1"},
        [11080] = {"强化冲击", "强化冲击。\n\n效果：使你的火焰冲击法术的冷却时间减少 1 秒，并使你的奥术冲击法术的暴击几率提高 2%。", "SpellTranslation", "等级 2"},
        [11083] = {"燃烧之魂", "使你的火焰法术因受到伤害而损失的施法时间缩短 35%，并使火焰法术造成的威胁值降低 5%。\n\n效果：让你的火焰法术在受到伤害时有 35% 的几率不损失施法时间，并减少你的火焰法术造成的威胁 5%。", "SpellTranslation", "等级 1"},
        [11094] = {"熔岩护盾", "使你的防护火焰结界有 10% 几率反射火焰法术，并使熔岩护甲有 1% 几率影响远程和法术攻击者。\n\n效果：使你的火焰结界在激活时有 10% 的几率反射火焰法术。此外，你的熔岩护甲有 50% 的几率影响远程和法术攻击。", "SpellTranslation", "等级 1"},
        [11095] = {"强化灼烧", "你的灼烧有 33% 几率使目标更容易受到火焰伤害，受到的火焰伤害提高 3%，持续 30 秒，最多叠加 5 次。\n\n效果：你的灼烧法术有 33% 的几率使你的目标容易受到火焰伤害。该漏洞使目标受到的火焰伤害提高 3%，持续 30 秒。最多可叠加 5 次。", "SpellTranslation", "等级 1"},
        [11100] = {"烈焰投掷", "使你的火焰法术射程提高 3 码。\n\n效果：使你的火焰法术范围增加 3 码。", "SpellTranslation", "等级 1"},
        [11103] = {"冲击", "你的火焰法术有 0% 几率使目标昏迷 2 秒。\n\n效果：让你的火焰法术有 2% 的几率使目标昏迷 2 秒。", "SpellTranslation", "等级 1"},
        [11108] = {"强化烈焰风暴", "使你的烈焰风暴暴击几率提高 5%，施法时间缩短 0.001 秒。\n\n效果：使你的烈焰打击法术的暴击几率提高 5%。", "SpellTranslation", "等级 1"},
        [11113] = {"冲击波", "从施法者身边放出烈焰波，对 10 码范围内所有敌人造成 154 到 187 点火焰伤害，并使其眩晕 6 秒。\n\n效果：眩晕。", "SpellTranslation", "等级 1"},
        [11115] = {"火焰重击", "使相关法术的暴击几率提高 2%。\n\n效果：使你的火焰法术的暴击率提高 2%。", "SpellTranslation", "等级 1"},
        [11119] = {"点燃", "你的火焰法术暴击会使目标在 4 秒内额外受到相当于该次法术伤害 1% 的火焰伤害。\n\n效果：你的火焰伤害法术造成的暴击会导致目标在 4 秒内燃烧，造成额外 8% 的法术伤害。", "SpellTranslation", "等级 1"},
        [11120] = {"点燃", "你的火焰法术暴击会使目标在 4 秒内额外受到相当于该次法术伤害 1% 的火焰伤害。\n\n效果：你的火焰伤害法术造成的暴击会导致目标在 4 秒内燃烧，造成额外 16% 的法术伤害。", "SpellTranslation", "等级 2"},
        [11124] = {"火焰强化", "使你的火焰法术伤害提高 2%。\n\n效果：使你的火焰法术造成的伤害提高 2%。", "SpellTranslation", "等级 1"},
        [11129] = {"燃烧", "激活后，每次火焰伤害法术命中都会使你的火焰法术暴击几率提高 10%。该效果持续到你造成 3 次火焰法术暴击为止。\n\n效果：当激活时，该法术会使你的每次火焰伤害法术命中使你的火焰伤害法术暴击率提高 10%。此效果会持续到你用火焰法术造成 3 次暴击为止。", "SpellTranslation"},
        [11131] = {"Icicle", "移动速度降低 50%。", "SpellTranslation"},
        [11151] = {"刺骨寒冰", "使你的冰霜法术伤害提高 2%。\n\n效果：使你的冰霜法术造成的伤害提高 2%。对于免疫火焰伤害的敌人，此效果会增加三倍。", "SpellTranslation", "等级 1"},
        [11160] = {"冰霜导能", "使你的所有法术法力消耗降低 5%，冰霜法术造成的威胁值降低 4%。\n\n效果：将你的冰霜法术的法力消耗降低 5%，并将你的冰霜法术造成的威胁降低 4%。", "SpellTranslation", "等级 1"},
        [11165] = {"强化冰霜新星", "使你的冰霜新星冷却时间缩短 2000 秒。\n\n效果：减少冰霜新星法术的冷却时间 2 秒。", "SpellTranslation", "等级 1"},
        [11170] = {"碎冰", "使你的所有法术对被冻结目标的暴击几率提高 1%。\n\n效果：使你所有法术对冰冻目标的暴击率提高 10%。", "SpellTranslation", "等级 1"},
        [11175] = {"永冻", "使你的寒冷效果持续时间延长 1000%，目标移动速度额外降低 4%，并使目标受到的治疗效果降低 1%。\n\n效果：使你的冰冷效果的持续时间增加 1 秒，并使目标的速度额外降低 4%。", "SpellTranslation", "等级 1"},
        [11180] = {"深冬之寒", "你的冰霜伤害法术有 20% 几率使目标受到冰霜法术暴击几率提高 0%，持续 15 秒，最多叠加 5 次。\n\n效果：使你的冰霜伤害法术有 20% 的几率施加凛冬之寒效果，从而使冰霜法术暴击目标的几率提高 2%，持续 15 秒。最多可叠加 5 次。", "SpellTranslation", "等级 1"},
        [11185] = {"强化暴风雪", "使你的暴风雪附带寒冷效果，令目标移动速度降低 1%，持续 1.5 秒。\n\n效果：为你的暴风雪法术添加冰寒效果。该效果使目标的移动速度降低 30%。持续1.5秒。", "SpellTranslation", "等级 1"},
        [11189] = {"冰霜障壁", "冰霜障壁。\n\n效果：使你的冰霜护甲和冰甲护甲法术所提供的护甲和抗性提高 15%。此外，在激活时，你的冰霜结界有 10% 的几率反射冰霜法术和效果。", "SpellTranslation", "等级 1"},
        [11190] = {"强化冰锥术", "使你的冰锥术伤害提高 15%。\n\n效果：使你的冰锥法术造成的伤害提高 15%。", "SpellTranslation", "等级 1"},
        [11197] = {"破甲", "终结技，暴露目标弱点，使其护甲降低1455点。对已经被破甲的目标再次使用会延长破甲持续时间，最多延长至60秒。持续时间随连击点数增加：\n1点：8秒\n2点：16秒\n3点：24秒\n4点：32秒\n5点：40秒", "SpellTranslation", "等级 4"},
        [11198] = {"破甲", "终结技，暴露目标弱点，使其护甲降低1800点。对已经被破甲的目标再次使用会延长破甲持续时间，最多延长至60秒。持续时间随连击点数增加：\n1点：8秒\n2点：16秒\n3点：24秒\n4点：32秒\n5点：40秒", "SpellTranslation", "等级 5"},
