        [11717] = {"鲁莽诅咒", "用鲁莽诅咒目标，使其近战攻击强度提高 90 点，但护甲降低 600 点，持续 2分钟。被诅咒的敌人不会逃跑，并会忽略恐惧和惊骇效果。同一术士对同一目标只能激活一个诅咒。\n\n效果：近战攻击强度提高 90 点，护甲降低 600 点；目标不会逃跑并会忽略恐惧和惊骇效果。", "SpellTranslation", "等级 4"},
        [11719] = {"语言诅咒", "迫使目标说恶魔语，使所有法术的施法时间延长 60%，持续 30秒。同一术士对同一目标只能激活一个诅咒。\n\n效果：正在说恶魔语，施法时间延长 60%。", "SpellTranslation", "等级 2"},
        [11721] = {"元素诅咒", "诅咒目标 5分钟，使其奥术、火焰、冰霜、自然和暗影抗性降低 60 点，并使其受到的魔法伤害提高 8%。同一术士对同一目标只能激活一个诅咒。\n\n效果：奥术、火焰、冰霜、自然和暗影抗性降低 60 点，受到的魔法伤害提高 8%。", "SpellTranslation", "等级 2"},
        [11722] = {"元素诅咒", "诅咒目标 5分钟，使其奥术、火焰、冰霜、自然和暗影抗性降低 75 点，并使其受到的魔法伤害提高 10%。同一术士对同一目标只能激活一个诅咒。\n\n效果：奥术、火焰、冰霜、自然和暗影抗性降低 75 点，受到的魔法伤害提高 10%。", "SpellTranslation", "等级 3"},
        [11725] = {"奴役恶魔", "奴役最高 47 级的目标恶魔，迫使其服从你的命令。被奴役时，恶魔攻击间隔延长 40%，施法速度降低 30%，最多持续 5分钟。反复奴役同一恶魔会更难成功。\n\n效果：被奴役。", "SpellTranslation", "等级 2"},
