        [20153] = {"献祭", "点燃附近敌人，每 1 秒造成 25 点火焰伤害，持续 15秒。", "SpellTranslation", "等级 1"},
        [20162] = {"十字军圣印", "圣骑士被十字军之魂附体，持续30分钟，提高59点近战攻击强度。圣骑士的攻击速度提高40%，但每次攻击造成的伤害会降低。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的神圣伤害提高最多35点。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击强度提高59点。近战攻击速度提高40%，但伤害降低。", "SpellTranslation", "等级 2"},
        [20164] = {"公正圣印", "圣骑士被公正之魂附体，持续30分钟，使其每次近战攻击都有一定几率使目标昏迷。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续20秒，防止其逃跑。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率使目标昏迷。", "SpellTranslation", "等级 1"},
        [20165] = {"光明圣印", "圣骑士被神圣之光附体，持续30分钟，使其每次近战攻击都有一定几率使圣骑士恢复39点生命值。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的近战攻击和法术攻击有一定几率使攻击者恢复25点生命值。如果攻击者生命值已满，则在该审判成功治疗前，其受到的治疗效果提高5%。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率为你恢复39点生命值。", "SpellTranslation", "等级 1"},
        [20166] = {"智慧圣印", "圣骑士被神圣智慧附体，持续30分钟，使其每次近战攻击都有一定几率使圣骑士恢复50点法力值。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续20秒，使其受到的近战攻击和法术攻击有一定几率为攻击者恢复33点法力值。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率恢复50点法力值。", "SpellTranslation", "等级 1"},
        [20170] = {"昏迷。", "昏迷。", "SpellTranslation"},
        [20174] = {"守护者的宠爱", "使你的保护之手冷却时间缩短 60 秒，并使自由之手持续时间延长 2 秒。\n\n效果：使你的保护之手的冷却时间减少 60 秒，并使你的自由之手的持续时间增加 2 秒。", "SpellTranslation", "等级 1"},
