        [20305] = {"十字军圣印", "圣骑士被十字军之魂附体，持续30分钟，提高108点近战攻击强度。圣骑士的攻击速度提高40%，但每次攻击造成的伤害会降低。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的神圣伤害提高最多58点。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击强度提高108点。近战攻击速度提高40%，但伤害降低。", "SpellTranslation", "等级 3"},
        [20306] = {"十字军圣印", "圣骑士被十字军之魂附体，持续30分钟，提高167点近战攻击强度。圣骑士的攻击速度提高40%，但每次攻击造成的伤害会降低。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的神圣伤害提高最多92点。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击强度提高167点。近战攻击速度提高40%，但伤害降低。", "SpellTranslation", "等级 4"},
        [20307] = {"十字军圣印", "圣骑士被十字军之魂附体，持续30分钟，提高254点近战攻击强度。圣骑士的攻击速度提高40%，但每次攻击造成的伤害会降低。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的神圣伤害提高最多127点。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击强度提高254点。近战攻击速度提高40%，但伤害降低。", "SpellTranslation", "等级 5"},
