        [20335] = {"强化十字军打击", "除了原有效果外，你的十字军打击还会使针对该目标的所有法术和攻击的暴击几率额外提高1%。\n\n效果：除了正常效果外，你的十字军审判法术还将提高针对该目标的所有法术和攻击的暴击率额外 1%。", "SpellTranslation", "等级 1"},
        [20336] = {"强化十字军打击", "除了原有效果外，你的十字军打击还会使针对该目标的所有法术和攻击的暴击几率额外提高2%。\n\n效果：除了正常效果外，你的十字军审判法术还将提高针对该目标的所有法术和攻击的暴击率额外2%。", "SpellTranslation", "等级 2"},
        [20337] = {"强化十字军打击", "除了原有效果外，你的十字军打击还会使针对该目标的所有法术和攻击的暴击几率额外提高3%。\n\n效果：除了正常效果外，你的十字军审判法术还会使针对该目标的所有法术和攻击的暴击率额外提高 3%。", "SpellTranslation", "等级 3"},
        [20347] = {"光明圣印", "圣骑士被神圣之光附体，持续30分钟，使其每次近战攻击都有一定几率使圣骑士恢复39点生命值。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的近战攻击和法术攻击有一定几率使攻击者恢复25点生命值。如果攻击者生命值已满，则在该审判成功治疗前，其受到的治疗效果提高5%。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率为你恢复53点生命值。", "SpellTranslation", "等级 2"},
        [20348] = {"光明圣印", "圣骑士被神圣之光附体，持续30分钟，使其每次近战攻击都有一定几率使圣骑士恢复39点生命值。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的近战攻击和法术攻击有一定几率使攻击者恢复25点生命值。如果攻击者生命值已满，则在该审判成功治疗前，其受到的治疗效果提高5%。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率为你恢复76点生命值。", "SpellTranslation", "等级 3"},
        [20349] = {"光明圣印", "圣骑士被神圣之光附体，持续30分钟，使其每次近战攻击都有一定几率使圣骑士恢复39点生命值。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续，使其受到的近战攻击和法术攻击有一定几率使攻击者恢复25点生命值。如果攻击者生命值已满，则在该审判成功治疗前，其受到的治疗效果提高5%。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率为你恢复94点生命值。", "SpellTranslation", "等级 4"},
        [20356] = {"智慧圣印", "圣骑士被神圣智慧附体，持续30分钟，使其每次近战攻击都有一定几率使圣骑士恢复71点法力值。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续20秒，使其受到的近战攻击和法术攻击有一定几率为攻击者恢复46点法力值。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率恢复71点法力值。", "SpellTranslation", "等级 2"},
        [20357] = {"智慧圣印", "圣骑士被神圣智慧附体，持续30分钟，使其每次近战攻击都有一定几率使圣骑士恢复90点法力值。同一时间内圣骑士身上只能激活一种圣印。\n\n释放这种圣印的能量将对敌人进行审判，持续20秒，使其受到的近战攻击和法术攻击有一定几率为攻击者恢复59点法力值。你的近战攻击会刷新该法术的持续时间。每个圣骑士在同一时间内只能激活一种审判效果。\n\n效果：近战攻击有一定几率恢复90点法力值。", "SpellTranslation", "等级 3"},
        [20359] = {"神圣圣光", "使你的圣光术、光明圣印和光明审判的暴击几率提高2%。\n\n效果：使你的圣光、光之印记和光之审判法术的暴击率提高 2%，并减少光之审判产生的威胁 33%。", "SpellTranslation", "等级 1"},
        [20360] = {"神圣圣光", "使你的圣光术、光明圣印和光明审判的暴击几率提高4%。\n\n效果：使你的圣光、光之印记、光之审判法术的暴击率提高4%，并减少光之审判产生的威胁67%。", "SpellTranslation", "等级 2"},
        [20361] = {"神圣圣光", "使你的圣光术、光明圣印和光明审判的暴击几率提高6%。\n\n效果：使你的圣光、光之印记、光之审判法术的暴击率提高6%，并减少光之审判产生的威胁100%。", "SpellTranslation", "等级 3"},
        [20375] = {"命令圣印", "使圣骑士有几率额外造成相当于普通武器伤害 70% 的神圣伤害，持续。切换到其他圣印时保留 0.5 秒。\n\n释放此圣印的能量会审判敌人，立即造成神圣伤害；若目标昏迷或瘫痪，则造成全额伤害。\n\n效果：近战攻击有一定几率造成额外的神圣伤害。", "SpellTranslation", "等级 1"},
        [20425] = {"命令审判", "释放命令圣印的能量，立即对敌人造成神圣伤害；若目标昏迷或瘫痪，则造成全额伤害。", "SpellTranslation", "等级 1"},
        [20467] = {"命令审判", "释放命令圣印的能量，立即对敌人造成神圣伤害；若目标昏迷或瘫痪，则造成全额伤害。", "SpellTranslation", "等级 1"},
        [20468] = {"强化正义之怒", "当正义之怒处于激活状态时，所有受到的伤害降低2%，并使正义之怒法术产生的威胁值提高16%。\n\n效果：当正义之怒激活时，受到的所有伤害都会减少 2%，并使正义之怒法术产生的威胁量增加 16%。", "SpellTranslation", "等级 1"},
        [20469] = {"强化正义之怒", "当正义之怒处于激活状态时，所有受到的伤害降低4%，并使正义之怒法术产生的威胁值提高33%。\n\n效果：当正义之怒激活时，受到的所有伤害都会减少 4%，并使正义之怒法术产生的威胁量增加 33%。", "SpellTranslation", "等级 2"},
        [20470] = {"强化正义之怒", "当正义之怒处于激活状态时，所有受到的伤害降低6%，并使正义之怒法术产生的威胁值提高50%。\n\n效果：当正义之怒激活时，受到的所有伤害都会减少 6%，并使正义之怒法术产生的威胁量增加 50%。", "SpellTranslation", "等级 3"},
        [20473] = {"神圣震击", "用神圣能量冲击目标，造成 1 到 1 点神圣伤害，或为友方目标恢复 1 到 1 点生命值。\n\n效果：用神圣能量轰击目标，对敌人造成 277 点神圣伤害，或对盟友造成 351 点治疗。", "SpellTranslation", "等级 1"},
        [20484] = {"复生", "使死去的玩家复活，并使其拥有 400 点生命值和 400 点法力值。可在战斗中使用。", "SpellTranslation", "等级 1"},
        [20487] = {"强化制裁之锤", "使你的制裁之锤冷却时间缩短 5000 秒。\n\n效果：减少正义之锤法术的冷却时间 5 秒。", "SpellTranslation", "等级 1"},
