        [27175] = {"神圣震击", "用神圣能量冲击目标，造成 1061 到 1150 点神圣伤害，或为友方目标恢复 1 到 1 点生命值。", "SpellTranslation", "等级 4"},
        [27176] = {"神圣震击", "用神圣能量冲击目标，造成 693 到 750 点神圣伤害，或为友方目标恢复 1 到 1 点生命值。", "SpellTranslation", "等级 4"},
        [27179] = {"神圣之盾", "格挡几率提高 30%，持续 10秒；激活期间每次格挡攻击都会造成 155 点神圣伤害。神圣之盾造成的伤害产生额外 35% 威胁值，拥有 8 次充能。\n\n效果：格挡几率提高30%。格挡时对攻击者造成155点神圣伤害。神圣之盾造成的伤害产生额外35%的威胁值。1次充能。", "SpellTranslation", "等级 4"},
        [27180] = {"愤怒之锤", "投掷神圣之锤，造成 665 到 736 点神圣伤害。只能对生命值低于 20% 的敌人使用。", "SpellTranslation", "等级 4"},
        [27209] = {"暗影箭", "向敌人发射暗影箭，造成 541 到 604 点暗影伤害。", "SpellTranslation", "等级 11"},
        [27210] = {"灼热之痛", "灼烧敌方目标，造成 243 到 288 点火焰伤害，并产生大量威胁值。", "SpellTranslation", "等级 7"},
        [27211] = {"灵魂之火", "燃烧敌人的灵魂，造成 839 到 1052 点火焰伤害。", "SpellTranslation", "等级 3"},
        [27212] = {"火焰之雨", "召唤火焰之雨灼烧目标区域的敌人，在 8秒内造成 1808 点火焰伤害。该持续伤害可以暴击。\n\n效果：每 2 秒造成 452 点火焰伤害。", "SpellTranslation", "等级 5"},
        [27213] = {"地狱烈焰", "点燃施法者周围区域，每 1 秒对自身造成 306 点火焰伤害，并对附近所有敌人造成 306 点火焰伤害，持续 15秒。\n\n效果：对自身和附近所有敌人造成火焰伤害。", "SpellTranslation", "等级 4"},
        [27214] = {"地狱烈焰效果", "每秒受到 306 点火焰伤害。", "SpellTranslation", "等级 4"},
        [27215] = {"献祭", "灼烧敌人，造成 327 点火焰伤害，并在 15秒内额外造成 615 点火焰伤害。\n\n效果：每 3 秒造成 123 点火焰伤害。", "SpellTranslation", "等级 9"},
        [27216] = {"腐蚀术", "腐蚀目标，在 18秒内造成 900 点暗影伤害。\n\n效果：每 3 秒造成 150 点暗影伤害。", "SpellTranslation", "等级 8"},
        [27217] = {"吸取灵魂", "吸取目标的灵魂，在 15秒内造成 620 点暗影伤害；根据目标已损失生命值，伤害最多提高 40%。如果目标在引导期间死亡且可提供经验值或荣誉，施法者获得一块灵魂碎片。\n\n效果：每 3 秒造成 124 点暗影伤害。", "SpellTranslation", "等级 5"},
        [27218] = {"痛苦诅咒", "使目标痛苦不堪，在 24秒内造成 1356 点暗影伤害。伤害开始较低，随后逐渐增强。同一术士对同一目标只能激活一个诅咒。\n\n效果：每 2 秒造成 113 点暗影伤害。", "SpellTranslation", "等级 7"},
        [27219] = {"吸取生命", "每 1 秒从目标身上转移 87 点生命值给施法者，持续 5秒。\n\n效果：每 1 秒吸取 87 点生命值给施法者。", "SpellTranslation", "等级 7"},
        [27220] = {"吸取生命", "每 1 秒从目标身上转移 108 点生命值给施法者，持续 5秒。\n\n效果：每 1 秒吸取 108 点生命值给施法者。", "SpellTranslation", "等级 8"},
        [27221] = {"吸取法力", "每 1 秒从目标身上转移 169 点法力值给施法者，持续 5秒。\n\n效果：每 1 秒吸取 169 点法力值给施法者。", "SpellTranslation", "等级 5"},
        [27222] = {"生命分流", "将 580 点生命值转化为 580 点法力值。", "SpellTranslation", "等级 7"},
        [27223] = {"死亡缠绕", "使敌方目标因恐惧逃跑 3秒，并造成 519 到 520 点暗影伤害。施法者恢复等同于伤害量 100% 的生命值。\n\n效果：惊骇。", "SpellTranslation", "等级 4"},
        [27224] = {"虚弱诅咒", "使目标近战攻击强度降低 257 点，持续 2分钟。同一术士对同一目标只能激活一个诅咒。\n\n效果：近战攻击强度降低 257 点。", "SpellTranslation", "等级 7"},
        [27226] = {"鲁莽诅咒", "用鲁莽诅咒目标，使其近战攻击强度提高 135 点，但护甲降低 800 点，持续 2分钟。被诅咒的敌人不会逃跑，并会忽略恐惧和惊骇效果。同一术士对同一目标只能激活一个诅咒。\n\n效果：近战攻击强度提高 135 点，护甲降低 800 点；目标不会逃跑并会忽略恐惧和惊骇效果。", "SpellTranslation", "等级 5"},
        [27228] = {"元素诅咒", "诅咒目标 5分钟，使其奥术、火焰、冰霜、自然和暗影抗性降低 88 点，并使其受到的魔法伤害提高 10%。同一术士对同一目标只能激活一个诅咒。\n\n效果：奥术、火焰、冰霜、自然和暗影抗性降低 88 点，受到的魔法伤害提高 10%。", "SpellTranslation", "等级 4"},
        [27230] = {"制造治疗石", "制造一块治疗石，使用后可立即恢复 2080 点生命值。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 6"},
        [27238] = {"制造灵魂石", "制造一块灵魂石。灵魂石可以储存一个目标的灵魂；如果目标在灵魂被储存期间死亡，将能以 2900 点生命值和 2900 点法力值复活。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 6"},
        [27241] = {"咕唧", "右键点击召唤或解散小鱼人格奇。", "SpellTranslation"},
        [27243] = {"腐蚀之种", "在敌方目标体内埋下恶魔之种，在 18秒内造成 666 点暗影伤害。当目标承受 1308 点总伤害或死亡时，种子爆炸，对目标周围 15 码内所有其他敌人造成 633 点暗影伤害。同一术士对同一目标只能激活一个腐蚀术效果。\n\n效果：每 3 秒造成 111 点暗影伤害。受到 1308 点总伤害或死亡后爆炸。", "SpellTranslation", "等级 1"},
        [27250] = {"制造火焰石", "制造一块火焰石，可为主手武器附魔，使每次攻击有几率额外造成 1 点火焰伤害。装备火焰石还会使火焰法术伤害提高 1 点。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 5"},
