        [47833] = {"腐蚀之种", "在敌方目标体内埋下恶魔之种，在 18秒内造成 1296 点暗影伤害。当目标承受 1296 点总伤害或死亡时，种子爆炸，对目标周围 15 码内所有其他敌人造成 1383 点暗影伤害。同一术士对同一目标只能激活一个腐蚀术效果。\n\n效果：每 3 秒造成 216 点暗影伤害。受到 1296 点总伤害或死亡后爆炸。", "SpellTranslation", "等级 2"},
        [47834] = {"腐蚀之种", "在敌方目标体内埋下恶魔之种，在 18秒内造成 1518 点暗影伤害。当目标承受 1518 点总伤害或死亡时，种子爆炸，对目标周围 15 码内所有其他敌人造成 1633 点暗影伤害。同一术士对同一目标只能激活一个腐蚀术效果。\n\n效果：每 3 秒造成 253 点暗影伤害。受到 1518 点总伤害或死亡后爆炸。", "SpellTranslation", "等级 3"},
        [47835] = {"腐蚀之种", "在敌方目标体内埋下恶魔之种，在 18秒内造成 1296 点暗影伤害。当目标承受 1296 点总伤害或死亡时，种子爆炸，对目标周围 15 码内所有其他敌人造成 1383 点暗影伤害。同一术士对同一目标只能激活一个腐蚀术效果。\n\n效果：每 3 秒造成 216 点暗影伤害。受到 1296 点总伤害或死亡后爆炸。", "SpellTranslation", "等级 2"},
        [47836] = {"腐蚀之种", "在敌方目标体内埋下恶魔之种，在 18秒内造成 1518 点暗影伤害。当目标承受 1518 点总伤害或死亡时，种子爆炸，对目标周围 15 码内所有其他敌人造成 1633 点暗影伤害。同一术士对同一目标只能激活一个腐蚀术效果。\n\n效果：每 3 秒造成 253 点暗影伤害。受到 1518 点总伤害或死亡后爆炸。", "SpellTranslation", "等级 3"},
        [47837] = {"烧尽", "对目标造成 485 到 564 点火焰伤害。如果目标受到献祭影响，则额外造成 121 点火焰伤害。", "SpellTranslation", "等级 3"},
        [47838] = {"烧尽", "对目标造成 582 到 677 点火焰伤害。如果目标受到献祭影响，则额外造成 145 点火焰伤害。", "SpellTranslation", "等级 4"},
        [47841] = {"痛苦无常", "暗影能量缓慢摧毁目标，在 15秒内造成 985 点暗影伤害。如果痛苦无常被驱散，会对驱散者造成 1773 点伤害并沉默 15秒。\n\n效果：每 3 秒造成 197 点暗影伤害。", "SpellTranslation", "等级 4"},
        [47843] = {"痛苦无常", "暗影能量缓慢摧毁目标，在 15秒内造成 1150 点暗影伤害。如果痛苦无常被驱散，会对驱散者造成 2070 点伤害并沉默 15秒。\n\n效果：每 3 秒造成 230 点暗影伤害。", "SpellTranslation", "等级 5"},
        [47846] = {"暗影之怒", "释放暗影之怒，造成 822 到 979 点暗影伤害，并使 8 码范围内所有敌人昏迷。", "SpellTranslation", "等级 4"},
        [47847] = {"暗影之怒", "释放暗影之怒，造成 968 到 1153 点暗影伤害，并使 8 码范围内所有敌人昏迷。", "SpellTranslation", "等级 5"},
        [47854] = {"被冻结在原地。", "被冻结在原地。", "SpellTranslation"},
        [47855] = {"吸取灵魂", "吸取目标的灵魂，在 15秒内造成 710 点暗影伤害；根据目标已损失生命值，伤害最多提高 40%。如果目标在引导期间死亡且可提供经验值或荣誉，施法者获得一块灵魂碎片。\n\n效果：每 3 秒造成 142 点暗影伤害。", "SpellTranslation", "等级 6"},
        [47856] = {"生命通道", "只要施法者保持引导，每秒将 520 点生命值输送给施法者的宠物，持续 10秒。\n\n效果：正在传输生命值。", "SpellTranslation", "等级 9"},
        [47857] = {"吸取生命", "每 1 秒从目标身上转移 133 点生命值给施法者，持续 5秒。\n\n效果：每 1 秒吸取 133 点生命值给施法者。", "SpellTranslation", "等级 9"},
        [47859] = {"死亡缠绕", "使敌方目标因恐惧逃跑 3秒，并造成 670 到 671 点暗影伤害。施法者恢复等同于伤害量 100% 的生命值。\n\n效果：惊骇。", "SpellTranslation", "等级 5"},
        [47860] = {"死亡缠绕", "使敌方目标因恐惧逃跑 3秒，并造成 790 到 791 点暗影伤害。施法者恢复等同于伤害量 100% 的生命值。\n\n效果：惊骇。", "SpellTranslation", "等级 6"},
        [47863] = {"痛苦诅咒", "使目标痛苦不堪，在 24秒内造成 1440 点暗影伤害。伤害开始较低，随后逐渐增强。同一术士对同一目标只能激活一个诅咒。\n\n效果：每 2 秒造成 120 点暗影伤害。", "SpellTranslation", "等级 8"},
        [47864] = {"痛苦诅咒", "使目标痛苦不堪，在 24秒内造成 1740 点暗影伤害。伤害开始较低，随后逐渐增强。同一术士对同一目标只能激活一个诅咒。\n\n效果：每 2 秒造成 145 点暗影伤害。", "SpellTranslation", "等级 9"},
        [47865] = {"元素诅咒", "诅咒目标 5分钟，使其奥术、火焰、冰霜、自然和暗影抗性降低 165 点，并使其受到的魔法伤害提高 13%。同一术士对同一目标只能激活一个诅咒。\n\n效果：奥术、火焰、冰霜、自然和暗影抗性降低 165 点，受到的魔法伤害提高 13%。", "SpellTranslation", "等级 5"},
        [47867] = {"厄运灾祸", "用迫近的厄运诅咒目标，在 1分钟后造成 7300 点暗影伤害。如果目标死于该伤害，有几率召唤一名末日守卫。不能对玩家施放。", "SpellTranslation", "等级 3"},
        [47871] = {"制造治疗石", "制造一块治疗石，使用后可立即恢复 3500 点生命值。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 7"},
        [47878] = {"制造治疗石", "制造一块治疗石，使用后可立即恢复 4280 点生命值。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 8"},
        [47884] = {"制造灵魂石", "制造一块灵魂石。灵魂石可以储存一个目标的灵魂；如果目标在灵魂被储存期间死亡，将能以 5300 点生命值和 5300 点法力值复活。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 7"},
        [47886] = {"制造法术石", "制造一块法术石，使用后可驱散施法者身上的所有有害魔法效果。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 5"},
        [47888] = {"制造法术石", "制造一块法术石，使用后可驱散施法者身上的所有有害魔法效果。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 6"},
        [47889] = {"恶魔护甲", "保护施法者，使护甲提高 2100 点，并使通过法术和效果获得的生命值提高 20%，持续 30分钟。同一时间只能激活一种护甲法术。\n\n效果：护甲提高 2100 点，通过法术和效果获得的生命值提高 20%。", "SpellTranslation", "等级 8"},
        [47890] = {"防护暗影结界", "吸收 2750 点暗影伤害，持续 30秒。\n\n效果：吸收 2750 点暗影伤害。", "SpellTranslation", "等级 5"},
        [47891] = {"防护暗影结界", "吸收 3300 点暗影伤害，持续 30秒。\n\n效果：吸收 3300 点暗影伤害。", "SpellTranslation", "等级 6"},
        [47892] = {"邪甲术", "邪能环绕施法者，使法术强度提高 150 点并额外提高相当于精神 30% 的数值，每 5 秒恢复最大生命值的 2%，持续 30分钟。同一时间只能激活一种护甲法术。\n\n效果：法术强度提高 150 点并额外提高精神的 30%，每 5 秒恢复最大生命值的 2%。", "SpellTranslation", "等级 3"},
        [47893] = {"邪甲术", "邪能环绕施法者，使法术强度提高 180 点并额外提高相当于精神 30% 的数值，每 5 秒恢复最大生命值的 2%，持续 30分钟。同一时间只能激活一种护甲法术。\n\n效果：法术强度提高 180 点并额外提高精神的 30%，每 5 秒恢复最大生命值的 2%。", "SpellTranslation", "等级 4"},
        [47897] = {"暗影烈焰", "施法者前方锥形范围内的目标受到 520 点暗影伤害，并在内额外受到 136 点火焰伤害。", "SpellTranslation", "等级 1"},
