        [47960] = {"暗影烈焰", "对施法者前方锥形区域内的目标造成一定量暗影伤害，并在一段时间内额外造成一定量火焰伤害。\n\n效果：每 3 秒造成 4 点火焰伤害。", "SpellTranslation"},
        [47964] = {"火焰箭", "向目标投掷火焰，造成一定量火焰伤害。", "SpellTranslation", "等级 9"},
        [47982] = {"血之契约", "使小队和团队成员的生命值提高。", "SpellTranslation", "等级 7"},
        [47983] = {"火焰之盾", "为友方小队或团队目标施加一个火焰护盾，使火焰抗性提高，且任何对该目标进行的攻击都会使攻击者受到一定量火焰伤害。持续一段时间。施法者无法对自己施放火焰护盾。\n\n效果：火焰抗性提高，被击中时对攻击者造成一定量火焰伤害。", "SpellTranslation", "等级 7"},
        [47984] = {"折磨", "嘲讽生物，提高其攻击虚空行者的几率。比折磨（等级 7）更有效。", "SpellTranslation", "等级 8"},
        [47985] = {"牺牲", "牺牲虚空行者的一部分生命值，为其主人提供一个可吸收一定量伤害的护盾，持续一段时间。只要护盾存在，施法就不会因受到伤害而被打断。\n\n效果：吸收所有伤害。", "SpellTranslation", "等级 8"},
        [47986] = {"牺牲", "牺牲虚空行者的一部分生命值，为其主人提供一个可吸收一定量伤害的护盾，持续一段时间。只要护盾存在，施法就不会因受到伤害而被打断。\n\n效果：吸收所有伤害。", "SpellTranslation", "等级 9"},
        [47987] = {"Consume Shadows", "虚空行者吞噬周围的阴影以增强体质，在一段时间内恢复一定量生命值，并大幅提高一定范围内附近所有友方目标的潜行侦测能力。无法在战斗中使用。\n\n效果：每隔一段时间治疗一定量伤害，并大幅提高一定范围内所有友方目标的潜行侦测能力。", "SpellTranslation", "等级 8"},
        [47988] = {"Consume Shadows", "虚空行者吞噬周围的阴影以增强体质，在一段时间内恢复一定量生命值，并大幅提高一定范围内附近所有友方目标的潜行侦测能力。无法在战斗中使用。\n\n效果：每隔一段时间治疗一定量伤害，并大幅提高一定范围内所有友方目标的潜行侦测能力。", "SpellTranslation", "等级 9"},
        [47989] = {"Suffering", "嘲讽一定范围内的所有敌人，提高其攻击虚空行者的几率，并使其命中几率降低一定比例，持续一段时间。比受难（等级 6）更有效。\n\n效果：命中几率降低一定比例。", "SpellTranslation", "等级 7"},
        [47990] = {"Suffering", "嘲讽一定范围内的所有敌人，提高其攻击虚空行者的几率，并使其命中几率降低一定比例，持续一段时间。比受难（等级 7）更有效。\n\n效果：命中几率降低一定比例。", "SpellTranslation", "等级 8"},
        [47991] = {"剧痛鞭笞", "一记瞬间发动的鞭笞攻击，对目标造成一定量暗影伤害。", "SpellTranslation", "等级 8"},
        [47992] = {"剧痛鞭笞", "一记瞬间发动的鞭笞攻击，对目标造成一定量暗影伤害。", "SpellTranslation", "等级 9"},
