        [48467] = {"飓风", "在目标区域制造猛烈风暴，每 1 秒对敌人造成 70 点自然伤害，并使敌人的攻击间隔延长 20%。持续 10秒。德鲁伊必须引导以维持法术。", "SpellTranslation", "等级 5"},
        [48468] = {"虫群", "虫群包围敌方目标，使其命中几率降低 3%，并在 12秒内造成 1290 点自然伤害。", "SpellTranslation", "等级 7"},
        [48469] = {"野性印记", "使友方目标的护甲提高 750 点，所有属性提高 37 点，所有抗性提高 54 点，持续 30分钟。", "SpellTranslation", "等级 9"},
        [48470] = {"野性赐福", "为小队或团队成员施加强效野性印记，使护甲提高 750 点，所有属性提高 37 点，所有抗性提高 54 点，持续 1小时。", "SpellTranslation", "等级 4"},
        [48477] = {"复生", "使死去的玩家复活，并使其拥有 6400 点生命值和 6400 点法力值。可在战斗中使用。", "SpellTranslation", "等级 7"},
