        [48480] = {"重殴", "使德鲁伊的下一次攻击额外造成 578 点伤害。", "SpellTranslation", "等级 10"},
        [48483] = {"感染伤口", "你的撕碎、重殴和裂伤会使目标感染伤口，使其移动速度降低 16%，攻击速度降低 6%，持续 12秒。", "SpellTranslation", "等级 1"},
        [48484] = {"感染伤口", "你的撕碎、重殴和裂伤会使目标感染伤口，使其移动速度降低 16%，攻击速度降低 6%，持续 12秒。", "SpellTranslation", "等级 2"},
        [48485] = {"感染伤口", "你的撕碎、重殴和裂伤会使目标感染伤口，使其移动速度降低 16%，攻击速度降低 6%，持续 12秒。", "SpellTranslation", "等级 3"},
        [48488] = {"狂风", "使你的飓风和台风造成的伤害提高 15%，旋风射程延长 2 码。", "SpellTranslation", "等级 1"},
        [48489] = {"强化裂伤", "使你的裂伤（熊）冷却时间缩短 1 秒，并使裂伤（猎豹）能量消耗降低 4 点。", "SpellTranslation", "等级 2"},
        [48491] = {"强化裂伤", "使你的裂伤（熊）冷却时间缩短 1.5 秒，并使裂伤（猎豹）能量消耗降低 6 点。", "SpellTranslation", "等级 3"},
        [48492] = {"丛林之王", "在熊或巨熊形态下使用激怒时，你造成的伤害提高 5%；猛虎之怒还会立即恢复 20 点能量。此外，熊形态、猎豹形态和巨熊形态的法力值消耗降低 20%。", "SpellTranslation", "等级 1"},
        [48494] = {"丛林之王", "在熊或巨熊形态下使用激怒时，你造成的伤害提高 10%；猛虎之怒还会立即恢复 40 点能量。此外，熊形态、猎豹形态和巨熊形态的法力值消耗降低 40%。", "SpellTranslation", "等级 2"},
        [48495] = {"丛林之王", "在熊或巨熊形态下使用激怒时，你造成的伤害提高 15%；猛虎之怒还会立即恢复 60 点能量。此外，熊形态、猎豹形态和巨熊形态的法力值消耗降低 60%。", "SpellTranslation", "等级 3"},
        [48496] = {"生命之种", "当你用迅捷治愈、愈合、滋养或治疗之触对目标造成暴击治疗时，有33%的几率在目标身上种下一个生命之种，其数值相当于本次治疗量的30%。当目标下次受到攻击时，生命之种会绽放。持续15秒。", "SpellTranslation", "等级 1"},
        [48499] = {"生命之种", "当你用迅捷治愈、愈合、滋养或治疗之触对目标造成暴击治疗时，有66%的几率在目标身上种下一个生命之种，其数值相当于本次治疗量的30%。当目标下次受到攻击时，生命之种会绽放。持续15秒。", "SpellTranslation", "等级 2"},
        [48500] = {"生命之种", "当你用迅捷治愈、愈合、滋养或治疗之触对目标造成暴击治疗时，有100%的几率在目标身上种下一个生命之种，其数值相当于本次治疗量的30%。当目标下次受到攻击时，生命之种会绽放。持续15秒。", "SpellTranslation", "等级 3"},
        [48505] = {"星辰坠落", "从天空召唤流星攻击施法者周围 30 码内的所有目标，每颗流星造成 145 点奥术伤害，并对目标周围 26 码内其他敌人造成 26 点奥术伤害。最多召唤 20 颗流星，持续 10秒。动物形态、坐骑或失去角色控制会压制该效果。", "SpellTranslation", "等级 1"},
        [48506] = {"大地与月亮", "你的愤怒和星火术有 100% 几率施加大地与月亮效果，使目标受到的法术伤害提高 4%，持续 12秒。此外，你的法术伤害提高 2%。", "SpellTranslation", "等级 1"},
        [48510] = {"大地与月亮", "你的愤怒和星火术有 100% 几率施加大地与月亮效果，使目标受到的法术伤害提高 4%，持续 12秒。此外，你的法术伤害提高 4%。", "SpellTranslation", "等级 2"},
        [48511] = {"大地与月亮", "你的愤怒和星火术有 100% 几率施加大地与月亮效果，使目标受到的法术伤害提高 4%，持续 12秒。此外，你的法术伤害提高 6%。", "SpellTranslation", "等级 3"},
        [48514] = {"狂风", "使你的飓风和台风造成的伤害提高 30%，旋风射程延长 4 码。", "SpellTranslation", "等级 2"},
        [48516] = {"日月双蚀", "当星火术暴击时，有 33% 几率使愤怒伤害提高 40%。当愤怒暴击时，有 19.8% 几率使星火术暴击几率提高 40%。每种效果持续 15秒，各自拥有 30 秒独立冷却时间，且不能同时发生。", "SpellTranslation", "等级 1"},
        [48521] = {"日月双蚀", "当星火术暴击时，有 66% 几率使愤怒伤害提高 40%。当愤怒暴击时，有 39.6% 几率使星火术暴击几率提高 40%。每种效果持续 15秒，各自拥有 30 秒独立冷却时间，且不能同时发生。", "SpellTranslation", "等级 2"},
        [48525] = {"日月双蚀", "当星火术暴击时，有 100% 几率使愤怒伤害提高 40%。当愤怒暴击时，有 60% 几率使星火术暴击几率提高 40%。每种效果持续 15秒，各自拥有 30 秒独立冷却时间，且不能同时发生。", "SpellTranslation", "等级 3"},
        [48532] = {"强化裂伤", "使你的裂伤（熊）冷却时间缩短 0.5 秒，并使裂伤（猎豹）能量消耗降低 2 点。", "SpellTranslation", "等级 1"},
        [48535] = {"强化生命之树", "在生命之树形态下，使你从物品获得的护甲加成提高67%，并使你的治疗法术强度提高，数值相当于你精神值的5%。", "SpellTranslation", "等级 1"},
        [48536] = {"强化生命之树", "在生命之树形态下，使你从物品获得的护甲加成提高133%，并使你的治疗法术强度提高，数值相当于你精神值的10%。", "SpellTranslation", "等级 2"},
        [48537] = {"强化生命之树", "在生命之树形态下，使你从物品获得的护甲加成提高200%，并使你的治疗法术强度提高，数值相当于你精神值的15%。", "SpellTranslation", "等级 3"},
        [48539] = {"回春", "你的回春术和野性成长每次生效时有 5% 几率恢复 8 点能量、4 点怒气、1% 法力值或 16 点符文能量。", "SpellTranslation", "等级 1"},
        [48544] = {"回春", "你的回春术和野性成长每次生效时有 10% 几率恢复 8 点能量、4 点怒气、1% 法力值或 16 点符文能量。", "SpellTranslation", "等级 2"},
        [48545] = {"回春", "你的回春术和野性成长每次生效时有 15% 几率恢复 8 点能量、4 点怒气、1% 法力值或 16 点符文能量。", "SpellTranslation", "等级 3"},
