        [49012] = {"翼龙钉刺", "射出带刺箭矢，使目标沉睡，最多持续 12 秒。任何伤害都会取消沉睡。当目标醒来时，钉刺会在 12 秒内造成 4920 点自然伤害。每个猎人同一目标只能激活一种钉刺。\n\n效果：正在沉睡。", "SpellTranslation", "等级 6"},
        [49013] = {"爆发", "使瘟疫打击的伤害提高一定比例，天灾打击的伤害提高一定比例。", "SpellTranslation", "等级 1"},
        [49015] = {"仇杀", "每当你杀死一个能提供经验或荣誉的目标时，为你恢复最多相当于最大生命值一定比例的生命值。", "SpellTranslation", "等级 1"},
        [49016] = {"狂暴", "使一个友方单位进入杀戮狂乱，持续一段时间。目标会进入激怒状态，使其造成的物理伤害提高一定比例，但每秒会损失相当于其最大生命值一定比例的生命值。\n\n效果：激怒。\n物理伤害提高一定比例。\n每秒损失最大生命值的一定比例。", "SpellTranslation"},
        [49018] = {"末日降临", "你的鲜血打击和心脏打击有一定比例的几率对目标施放一个免费的死亡缠绕。", "SpellTranslation", "等级 1"},
        [49020] = {"湮没", "", "SpellTranslation", "等级 1"},
        [49023] = {"莫格莱尼之力", "使你的血液沸腾、鲜血打击、死亡打击和心脏打击的暴击伤害加成提高一定比例。", "SpellTranslation", "等级 1"},
        [49024] = {"无情战斗", "你的冰冷触摸、凛风冲击、湮没和冰霜打击在攻击生命值低于35%的目标时额外造成一定比例的伤害。", "SpellTranslation", "等级 1"},
        [49027] = {"血虫", "你的武器命中有一定比例的几率使目标生成2至4只血虫。血虫会攻击你的敌人，并在造成伤害时为你恢复生命值，持续20秒或直到被杀死。", "SpellTranslation", "等级 1"},
        [49028] = {"符文刃舞", "召唤一把符文武器自动为你而战，持续一段时间，其攻击方式与死亡骑士相同，但造成的伤害降低一定比例。\n\n效果：你最近召唤了一把符文武器。", "SpellTranslation"},
        [49032] = {"墓穴热病", "你的疾病还会引起墓地热疫，使目标受到的疾病伤害提高一定比例。", "SpellTranslation", "等级 1"},
        [49036] = {"流行病", "使血之瘟疫和冰霜热疫的持续时间延长数秒。", "SpellTranslation", "等级 1"},
        [49039] = {"巫妖之躯", "汲取不洁能量变身为亡灵，持续一段时间。在此状态下，你免疫魅惑、恐惧和睡眠效果。\n\n效果：免疫魅惑、恐惧和睡眠。\n亡灵。", "SpellTranslation"},
        [49042] = {"坚韧", "使你从物品获得的护甲值提高一定比例，并使所有减速效果的持续时间缩短一定比例。", "SpellTranslation", "等级 1"},
        [49044] = {"奥术射击", "一次瞬发射击，造成 0 点加远程攻击强度 15% 的奥术伤害，并驱散 402 个魔法效果。", "SpellTranslation", "等级 10"},
        [49045] = {"奥术射击", "一次瞬发射击，造成 0 点加远程攻击强度 15% 的奥术伤害，并驱散 492 个魔法效果。", "SpellTranslation", "等级 11"},
        [49047] = {"多重射击", "发射多枚弹药，最多击中 3 个目标，并造成额外 333 点伤害。", "SpellTranslation", "等级 7"},
        [49048] = {"多重射击", "发射多枚弹药，最多击中 3 个目标，并造成额外 408 点伤害。", "SpellTranslation", "等级 8"},
        [49049] = {"瞄准射击", "一次瞄准射击，造成远程武器伤害再加 345 点伤害，并使目标受到的治疗效果降低 50%，持续 10 秒。\n\n效果：受到的治疗效果降低 50%。", "SpellTranslation", "等级 8"},
        [49050] = {"瞄准射击", "一次瞄准射击，造成远程武器伤害再加 408 点伤害，并使目标受到的治疗效果降低 50%，持续 10 秒。\n\n效果：受到的治疗效果降低 50%。", "SpellTranslation", "等级 9"},
        [49051] = {"稳固射击", "一次稳定射击，造成 198 点加远程攻击强度 20% 的伤害。若目标受到眩晕效果影响，额外造成 175 点伤害。", "SpellTranslation", "等级 3"},
        [49052] = {"稳固射击", "一次稳定射击，造成 252 点加远程攻击强度 20% 的伤害。若目标受到眩晕效果影响，额外造成 175 点伤害。", "SpellTranslation", "等级 4"},
        [49053] = {"献祭陷阱", "放置火焰陷阱，使第一个靠近的敌人在 15 秒内受到 1540 点加远程攻击强度 10% 的火焰伤害。陷阱存在 1 分钟。同一时间只能激活一个陷阱。\n\n效果：每 3 秒造成 308 点火焰伤害。", "SpellTranslation", "等级 7"},
