        [49067] = {"爆炸陷阱", "放置火焰陷阱，敌人靠近时爆炸，对 10 码范围内所有敌人造成 523 到 672 点加远程攻击强度 10% 的火焰伤害，并在 20 秒内额外造成 900 点火焰伤害。陷阱存在 1 分钟。同一时间只能激活一个陷阱。", "SpellTranslation", "等级 6"},
        [49071] = {"野性守护", "猎人与 40 码范围内的小队及团队成员获得野性守护，自然抗性提高 130 点。同一时间只能激活一种守护。", "SpellTranslation", "等级 4"},
