        [49092] = {"无法移动。", "无法移动。", "SpellTranslation"},
        [49137] = {"无尽寒冬", "你的力量提高一定比例，且心灵冰冻的消耗降低至10点符文能量。", "SpellTranslation", "等级 1"},
        [49140] = {"黑冰", "使你的冰霜和暗影伤害提高一定比例。", "SpellTranslation", "等级 1"},
        [49142] = {"冰霜符文武器", "为你的符文武器注入霜冻之力。在接下来的30分钟内，你的近战攻击有一定几率使目标在一段时间内受到的冰霜伤害提高一定比例。此效果最多可叠加10次。", "SpellTranslation"},
        [49143] = {"冰霜打击", "立即打击敌人，造成一定比例的武器伤害，并额外造成一定量冰霜伤害。", "SpellTranslation", "等级 1"},
