        [49146] = {"白马骑士", "你变得如死亡本身一样难以阻挡。所有对你施加的昏迷和恐惧效果持续时间缩短10%，并使你的骑乘速度提高10%。该效果不与其他提高移动速度的效果叠加。", "SpellTranslation", "等级 1"},
        [49149] = {"墓穴之寒", "你的冰链术、凛冽寒风、冰冷触摸和湮灭会产生额外的2.5点符文能量。", "SpellTranslation", "等级 1"},
        [49158] = {"尸体爆炸", "引爆一具尸体，对一定范围内的所有敌人造成一定量暗影伤害。如果目标不是尸体，则会使用附近的一具尸体。不会影响机械体或元素生物的尸体。", "SpellTranslation", "等级 1"},
        [49175] = {"强化冰冷触摸", "使你的冰冷触摸额外造成一定比例的伤害，并使你的冰霜热疫额外降低近战和远程攻击速度一定比例。", "SpellTranslation", "等级 1"},
        [49182] = {"刀锋屏障", "每当你的鲜血符文处于冷却状态时，你就会获得刀锋护甲效果，使你在接下来的内受到的伤害降低一定比例。", "SpellTranslation", "等级 1"},
        [49184] = {"凛风冲击", "以刺骨寒风冲击目标，对10码范围内的所有敌人造成一定量冰霜伤害。", "SpellTranslation", "等级 1"},
        [49186] = {"冰冷恐惧铠", "使近战攻击命中你的几率降低一定比例。", "SpellTranslation", "等级 1"},
        [49188] = {"白霜", "使你的冰冷触摸和湮没暴击几率提高一定比例，并且施放湮没有一定比例的几率重置凛风冲击的冷却时间，并使你的下一个凛风冲击不消耗符文。", "SpellTranslation", "等级 1"},
        [49189] = {"亡灵天灾之意志", "使你生命值降至一定比例以下的伤害或在你生命值处于一定比例以下时受到的伤害降低一定比例。", "SpellTranslation", "等级 1"},
        [49193] = {"复仇角斗士的虚空幼龙", "根据你的骑术提高移动速度。", "SpellTranslation"},
        [49194] = {"被烧毁的", "使受到你缠绕攻击的目标被邪恶的昆虫包围，在一段时间内受到相当于缠绕伤害一定比例的伤害，并防止目标身上的任何疾病效果被驱散。\n\n效果：正在受到邪恶虫群的伤害。疾病无法被驱散。", "SpellTranslation"},
        [49200] = {"适应", "当你被法术击中时，有一定比例的几率提高你对该系魔法的抗性，持续18秒。最多可叠加3层。", "SpellTranslation", "等级 1"},
        [49202] = {"冻原潜行者", "你的法术和技能对感染冰霜热疫的目标造成的伤害提高一定比例。同时使你的精准提高。", "SpellTranslation", "等级 1"},
        [49203] = {"饥饿之寒", "清除死亡骑士周围地面上的所有热量。一定范围内的敌人将被困在冰中，在一段时间内无法进行任何动作，并感染霜疫。敌人被视为处于冻结状态，但除了疾病以外的任何伤害都会打破冰冻。\n\n效果：被冻结。", "SpellTranslation", "等级 1"},
        [49206] = {"召唤石像鬼", "一只石像鬼飞入该区域，用受死亡骑士攻击强度加成的自然伤害轰击目标。持续一段时间。\n\n效果：正在受到石像鬼的攻击。", "SpellTranslation"},
        [49208] = {"收割", "每当你的鲜血打击或传染命中时，都有一定比例的几率使鲜血符文在激活时变为死亡符文。死亡符文可被视为鲜血、冰霜或邪恶符文。", "SpellTranslation", "等级 1"},
        [49217] = {"游荡瘟疫", "当你的疾病对敌人造成伤害时，有等同于你近战暴击几率的概率对该目标及八码范围内所有敌人造成一定比例的额外伤害。无视任何受到伤害就会取消效果的法术影响下的目标。", "SpellTranslation", "等级 1"},
        [49219] = {"血浆之刃", "你的自动攻击有一定比例的几率造成一次鲜血浸染打击，对目标造成一定比例的武器伤害，并且目标身上的每个疾病都会额外提高一定比例的伤害。", "SpellTranslation", "等级 1"},
        [49220] = {"不洁", "你的法术获得的攻击强度加成提高一定比例。", "SpellTranslation", "等级 1"},
        [49222] = {"盾墙", "伤害降低 1%。", "SpellTranslation"},
        [49223] = {"挽歌", "你的死亡打击、天灾打击和天灾打击会产生额外的2.5点符文能量。", "SpellTranslation", "等级 1"},
        [49224] = {"法术压制", "你受到的所有魔法伤害降低一定比例。此外，你的反魔法护罩可额外吸收一定比例的法术伤害。", "SpellTranslation", "等级 1"},
