        [49277] = {"先祖之魂", "使灵魂回归肉体，复活一名死亡目标，并使其拥有 1800 点生命值和 1800 点法力值。无法在战斗中施放。", "SpellTranslation", "等级 7"},
        [49278] = {"闪电之盾", "施法者被 3 个闪电球环绕。法术、近战或远程攻击命中施法者时，攻击者受到 13 点自然伤害，并消耗 1 个闪电球。闪电球每几秒最多触发一次，持续 10分钟。萨满同一时间只能激活一种元素护盾。", "SpellTranslation", "等级 10"},
        [49279] = {"闪电之盾", "施法者被 3 个闪电球环绕。法术、近战或远程攻击命中施法者时，攻击者受到 13 点自然伤害，并消耗 1 个闪电球。闪电球每几秒最多触发一次，持续 10分钟。萨满同一时间只能激活一种元素护盾。", "SpellTranslation", "等级 11"},
        [49280] = {"闪电之盾", "施法者被 3 个闪电球环绕。法术、近战或远程攻击命中施法者时，攻击者受到 13 点自然伤害，并消耗 1 个闪电球。闪电球每几秒最多触发一次，持续 10分钟。萨满同一时间只能激活一种元素护盾。\n\n效果：被击中时对攻击者造成325点自然伤害。3次充能。", "SpellTranslation", "等级 10"},
        [49281] = {"闪电之盾", "施法者被 3 个闪电球环绕。法术、近战或远程攻击命中施法者时，攻击者受到 13 点自然伤害，并消耗 1 个闪电球。闪电球每几秒最多触发一次，持续 10分钟。萨满同一时间只能激活一种元素护盾。\n\n效果：被击中时对攻击者造成380点自然伤害。3次充能。", "SpellTranslation", "等级 11"},
        [49283] = {"大地之盾", "以大地之盾保护目标，使其受到伤害时有 30% 几率避免施法被打断，并使攻击治疗被护盾保护的目标 300 点生命值。该效果每几秒最多触发一次，共有 6 层，持续 10分钟。同一时间只能对一个目标施放大地之盾，且一个目标同一时间只能拥有一种元素护盾。\n\n效果：受到伤害时施法或引导被打断的时间缩短30%，攻击为被护盾保护的目标治疗300。", "SpellTranslation", "等级 4"},
        [49284] = {"大地之盾", "以大地之盾保护目标，使其受到伤害时有 30% 几率避免施法被打断，并使攻击治疗被护盾保护的目标 337 点生命值。该效果每几秒最多触发一次，共有 6 层，持续 10分钟。同一时间只能对一个目标施放大地之盾，且一个目标同一时间只能拥有一种元素护盾。\n\n效果：受到伤害时施法或引导被打断的时间缩短30%，攻击为被护盾保护的目标治疗337。", "SpellTranslation", "等级 5"},
