        [51180] = {"大地之母的赐福", "使你的总法术急速提高 4%，并使生命绽放基础冷却时间缩短 4%。", "SpellTranslation", "等级 2"},
        [51181] = {"大地之母的赐福", "使你的总法术急速提高 6%，并使生命绽放基础冷却时间缩短 6%。", "SpellTranslation", "等级 3"},
        [51182] = {"大地之母的赐福", "使你的总法术急速提高 8%，并使生命绽放基础冷却时间缩短 8%。", "SpellTranslation", "等级 4"},
        [51183] = {"大地之母的赐福", "使你的总法术急速提高 10%，并使生命绽放基础冷却时间缩短 10%。", "SpellTranslation", "等级 5"},
        [51185] = {"丛林之王", "伤害提高 1%。", "SpellTranslation"},
        [51235] = {"Dan's Test Fireball", "发射一枚火球，造成 14 到 23 点火焰伤害，并在 8 秒内额外造成 4 点火焰伤害。\n\n效果：每 2 秒造成 1 点火焰伤害。", "SpellTranslation"},
        [51236] = {"Dan's Test Iceblast", "发射一枚火球，造成 14 到 23 点火焰伤害，并在 8 秒内额外造成 4 点火焰伤害。\n\n效果：每 2 秒造成 1 点火焰伤害。", "SpellTranslation"},
        [51267] = {"白马骑士", "你变得如死亡本身一样难以阻挡。所有对你施加的昏迷和恐惧效果持续时间缩短20%，并使你的骑乘速度提高20%。该效果不与其他提高移动速度的效果叠加。", "SpellTranslation", "等级 2"},
        [51268] = {"割碎", "使你的重殴和撕碎对流血目标造成的伤害提高 16%，并使凶猛撕咬对流血目标的暴击几率提高 20%。", "SpellTranslation", "等级 4"},
        [51269] = {"割碎", "使你的重殴和撕碎对流血目标造成的伤害提高 20%，并使凶猛撕咬对流血目标的暴击几率提高 25%。", "SpellTranslation", "等级 5"},
        [51271] = {"坚不可摧护甲", "用厚厚的冰层加固你的护甲，使你的护甲值提高一定比例，力量提高一定比例，持续一段时间。\n\n效果：护甲提高一定比例。\n力量提高一定比例。", "SpellTranslation"},
        [51294] = {"钓鱼", "装备鱼竿，寻找水域进行钓鱼。当水里的鱼漂溅起水花时，右键点击即可钓到鱼。技能越高，在高级区域钓鱼成功的几率就越高。", "SpellTranslation", "宗师"},
        [51296] = {"烹饪", "允许厨师学习神奇的烹饪配方。使你的烹饪技能上限达到450点。", "SpellTranslation", "宗师"},
        [51300] = {"锻造", "允许锻造师制造武器和护甲。使你的锻造技能上限达到450点。", "SpellTranslation", "宗师"},
        [51302] = {"制皮", "允许制皮师制造宗师级皮甲，最高技能上限为450点。", "SpellTranslation", "宗师"},
        [51304] = {"炼金术", "允许炼金师调制卓越的药水。使你的炼金技能上限达到450点。", "SpellTranslation", "宗师"},
