        [51313] = {"附魔", "允许附魔师为武器和护甲施加宗师级附魔。使你的附魔技能上限达到450点。", "SpellTranslation", "宗师"},
        [51316] = {"Lobotomize", "沉默。\n被缴械。", "SpellTranslation"},
        [51325] = {"尸体爆炸", "引爆一具尸体，对一定范围内的所有敌人造成一定量暗影伤害。如果目标不是尸体，则会使用附近的一具尸体。不会影响机械体或元素生物的尸体。", "SpellTranslation", "等级 2"},
