        [51489] = {"Skin of Earth", "使友方目标长出荆棘，被击中时对攻击者造成 3 点自然伤害，持续 10分钟。\n\n效果：对攻击者造成 3 点自然伤害。", "SpellTranslation"},
        [51490] = {"雷霆风暴", "召唤一道闪电为你注入能量并伤害 10 码范围内附近敌人。为你恢复 8% 法力值，对附近所有敌人造成 551 点自然伤害，并将其击退 20 码。可在昏迷状态下使用。", "SpellTranslation", "等级 1"},
        [51491] = {"Unrelenting Strike", "昏迷。", "SpellTranslation"},
        [51503] = {"Domination", "被魅惑。", "SpellTranslation"},
        [51505] = {"熔岩爆裂", "向目标投掷熔岩，造成 1012 点火焰伤害。如果目标受到你的烈焰震击影响，熔岩爆裂必定暴击。", "SpellTranslation", "等级 1"},
        [51514] = {"妖术", "将敌人变成青蛙。妖术期间目标无法攻击或施法，受到伤害可能中断效果。持续 30秒。同一时间只能妖术一个目标。只对人型生物和野兽有效。\n\n效果：无法攻击或施法。", "SpellTranslation"},
