        [51522] = {"强化风暴打击", "当你使用风暴打击时，有 100% 几率立即获得相当于基础法力值 20% 的法力值。", "SpellTranslation", "等级 2"},
        [51523] = {"大地之力", "你的地缚图腾脉冲有 50% 几率同时移除你和附近友方目标身上的所有移动限制效果，并使你的大地震击额外降低敌人攻击速度 5%。", "SpellTranslation", "等级 1"},
        [51524] = {"大地之力", "你的地缚图腾脉冲有 100% 几率同时移除你和附近友方目标身上的所有移动限制效果，并使你的大地震击额外降低敌人攻击速度 10%。", "SpellTranslation", "等级 2"},
