        [51526] = {"静电震击", "当你用近战攻击和技能造成伤害时，有 4% 几率消耗一层闪电之盾充能击中目标；你的闪电之盾额外获得 4 层充能。", "SpellTranslation", "等级 2"},
        [51527] = {"静电震击", "当你用近战攻击和技能造成伤害时，有 6% 几率消耗一层闪电之盾充能击中目标；你的闪电之盾额外获得 6 层充能。", "SpellTranslation", "等级 3"},
