        [51556] = {"先祖觉醒", "当你的治疗波、次级治疗波或激流造成暴击治疗时，召唤先祖之魂协助你，立即为 40 码内生命值百分比最低的友方小队或团队目标恢复相当于本次治疗量 10% 的生命值。", "SpellTranslation", "等级 1"},
        [51557] = {"先祖觉醒", "当你的治疗波、次级治疗波或激流造成暴击治疗时，召唤先祖之魂协助你，立即为 40 码内生命值百分比最低的友方小队或团队目标恢复相当于本次治疗量 20% 的生命值。", "SpellTranslation", "等级 2"},
        [51558] = {"先祖觉醒", "当你的治疗波、次级治疗波或激流造成暴击治疗时，召唤先祖之魂协助你，立即为 40 码内生命值百分比最低的友方小队或团队目标恢复相当于本次治疗量 30% 的生命值。", "SpellTranslation", "等级 3"},
        [51560] = {"强化大地之盾", "使你的大地之盾层数增加 1 层，并使大地之盾治疗效果提高 5%。", "SpellTranslation", "等级 1"},
        [51561] = {"强化大地之盾", "使你的大地之盾层数增加 2 层，并使大地之盾治疗效果提高 10%。", "SpellTranslation", "等级 2"},
        [51562] = {"潮汐奔涌", "当你施放治疗链或激流时，有 20% 几率使治疗波施法时间缩短 30%，并使次级治疗波暴击几率提高 25%，直到你施放 2 个此类法术。此外，治疗波额外获得相当于治疗加成 4% 的收益，次级治疗波额外获得相当于治疗加成 2% 的收益。", "SpellTranslation", "等级 1"},
        [51563] = {"潮汐奔涌", "当你施放治疗链或激流时，有 40% 几率使治疗波施法时间缩短 30%，并使次级治疗波暴击几率提高 25%，直到你施放 2 个此类法术。此外，治疗波额外获得相当于治疗加成 8% 的收益，次级治疗波额外获得相当于治疗加成 4% 的收益。", "SpellTranslation", "等级 2"},
        [51564] = {"潮汐奔涌", "当你施放治疗链或激流时，有 60% 几率使治疗波施法时间缩短 30%，并使次级治疗波暴击几率提高 25%，直到你施放 2 个此类法术。此外，治疗波额外获得相当于治疗加成 12% 的收益，次级治疗波额外获得相当于治疗加成 6% 的收益。", "SpellTranslation", "等级 3"},
        [51565] = {"潮汐奔涌", "当你施放治疗链或激流时，有 80% 几率使治疗波施法时间缩短 30%，并使次级治疗波暴击几率提高 25%，直到你施放 2 个此类法术。此外，治疗波额外获得相当于治疗加成 16% 的收益，次级治疗波额外获得相当于治疗加成 8% 的收益。", "SpellTranslation", "等级 4"},
        [51566] = {"潮汐奔涌", "当你施放治疗链或激流时，有 100% 几率使治疗波施法时间缩短 30%，并使次级治疗波暴击几率提高 25%，直到你施放 2 个此类法术。此外，治疗波额外获得相当于治疗加成 20% 的收益，次级治疗波额外获得相当于治疗加成 10% 的收益。", "SpellTranslation", "等级 5"},
