        [53323] = {"碎剑符文", "为你的双手符文武器附加一个符文，使招架几率提高4%，且缴械效果的持续时间缩短一定比例。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53331] = {"巫妖克星符文", "为你的符文武器附加一个符文，使你的武器攻击额外造成2%的火焰伤害，对亡灵目标的额外伤害则为4%。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53338] = {"猎人印记", "在目标身上施加猎人印记，使所有攻击者对该目标的远程攻击强度提高 500 点。每次被远程攻击命中后，远程攻击强度额外提高 500 点，最高 15500 点。此外，猎人始终可以看见该目标，即使目标潜行或隐形；目标也会显示在小地图上。持续 5 分钟。\n\n效果：所有攻击者对该目标的远程攻击强度提高 500 点，每次远程攻击命中后额外提高 500 点，最高 15500 点。", "SpellTranslation", "等级 5"},
        [53339] = {"猫鼬撕咬", "反击敌人，造成 280 点加攻击强度 20% 的伤害。只能在你躲闪后使用。", "SpellTranslation", "等级 6"},
        [53341] = {"烬冰符文", "为你的符文武器附加一个符文，使其有一定几率使你接下来的2次冰霜或暗影伤害攻击所造成的伤害提高一定比例。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53342] = {"碎咒符文", "为你的双手符文武器附加一个符文，使你偏转所有法术伤害的几率提高一定比例，且沉默效果的持续时间缩短一定比例。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53343] = {"锋冰符文", "为你的武器附加一个符文，使你的武器攻击额外造成2%的冰霜伤害，并提高敌人对你的冰霜攻击的易伤几率。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53344] = {"堕落十字军符文", "为你的符文武器附加一个符文，使其有一定几率为你恢复一定比例的生命值，并使你的总力量提高一定比例，持续一段时间。修改符文武器需要前往黑锋要塞的符文熔炉。", "SpellTranslation"},
        [53351] = {"杀戮射击", "尝试终结受伤目标，造成 205 点加远程攻击强度 40% 的伤害。只能对生命值低于 20% 的敌人使用。", "SpellTranslation", "等级 1"},
        [53352] = {"爆炸射击", "发射爆炸弹药，对目标造成 10 点火焰伤害，并在接下来 2 秒内每秒额外造成一次火焰伤害。\n\n效果：每秒受到火焰伤害。", "SpellTranslation"},
        [53359] = {"Chimera Shot - Scorpid", "造成 125% 武器伤害，并根据目标身上的钉刺刷新或触发额外效果。\n\n效果：被缴械。", "SpellTranslation"},
        [53365] = {"Unholy Strength", "力量提高 20%。", "SpellTranslation"},
        [53375] = {"神圣愤怒", "使愤怒之锤暴击几率提高 25%，复仇之怒冷却时间缩短 30 秒；复仇之怒激活时，你造成的所有伤害有 25% 无视伤害减免效果。", "SpellTranslation", "等级 1"},
        [53376] = {"神圣愤怒", "使愤怒之锤暴击几率提高 50%，复仇之怒冷却时间缩短 60 秒；复仇之怒激活时，你造成的所有伤害有 50% 无视伤害减免效果。", "SpellTranslation", "等级 2"},
        [53379] = {"迅捷惩戒", "你的光环还会使施法速度、远程攻击速度和近战攻击速度提高1%。", "SpellTranslation", "等级 1"},
        [53380] = {"正义复仇", "当你的审判、十字军打击和神圣风暴造成暴击时，目标会在8秒内额外受到相当于本次伤害10%的伤害。", "SpellTranslation", "等级 1"},
        [53381] = {"正义复仇", "当你的审判、十字军打击和神圣风暴造成暴击时，目标会在8秒内额外受到相当于本次伤害20%的伤害。", "SpellTranslation", "等级 2"},
        [53382] = {"正义复仇", "当你的审判、十字军打击和神圣风暴造成暴击时，目标会在8秒内额外受到相当于本次伤害30%的伤害。", "SpellTranslation", "等级 3"},
        [53385] = {"神圣风暴", "瞬发武器攻击，对 8 码范围内最多 4 个敌人造成 110% 武器伤害，并为最多 3 名小队或团队成员恢复相当于该伤害总量 25% 的生命值。", "SpellTranslation"},
        [53397] = {"活力", "", "SpellTranslation", "等级 1"},
        [53401] = {"狂暴", "你的宠物进入杀戮狂乱状态。成功的攻击有一定几率使其攻击强度提高一定比例。此效果最多可叠加若干次。持续一段时间。\n\n效果：命中可以提高宠物的攻击强度。", "SpellTranslation"},
        [53403] = {"Rabid Power", "攻击强度提高一定比例。", "SpellTranslation"},
        [53407] = {"公正审判", "释放圣印能量对敌人进行审判，持续20秒。使其无法逃跑且移动速度受到限制。具体的审判效果请参见各个圣印的说明。圣骑士在同一时间内只能激活一种审判效果。", "SpellTranslation"},
        [53408] = {"智慧审判", "审判目标，使攻击该目标的攻击和法术有几率为攻击者恢复 0 点法力值。", "SpellTranslation"},
        [53409] = {"雄狮之心", "使施加到你的宠物身上的所有昏迷和恐惧效果持续时间缩短一定比例。", "SpellTranslation", "等级 1"},
        [53411] = {"雄狮之心", "使施加到你的宠物身上的所有昏迷和恐惧效果持续时间缩短一定比例。", "SpellTranslation", "等级 2"},
        [53418] = {"Pierce Armor", "护甲降低 50%。", "SpellTranslation"},
        [53426] = {"舔舐伤口", "你的宠物在引导期间于内恢复其总生命值的一定比例。\n\n效果：每隔一段时间恢复最大生命值的一定比例。", "SpellTranslation"},
        [53427] = {"强效抗性", "使你的宠物受到的奥术、火焰、冰霜、自然和暗影魔法伤害降低一定比例。", "SpellTranslation", "等级 1"},
        [53428] = {"符文锻造", "允许死亡骑士在他们的武器上镌刻符文。", "SpellTranslation"},
        [53429] = {"强效抗性", "使你的宠物受到的奥术、火焰、冰霜、自然和暗影魔法伤害降低一定比例。", "SpellTranslation", "等级 2"},
        [53430] = {"强效抗性", "使你的宠物受到的奥术、火焰、冰霜、自然和暗影魔法伤害降低一定比例。", "SpellTranslation", "等级 3"},
