        [53654] = {"圣光道标", "目标成为圣光道标。你对 60 码范围内小队或团队成员施放的任何治疗法术，都会为圣光道标恢复相当于治疗量 1% 的生命值。同一时间只能有一个圣光道标，持续 1分钟。", "SpellTranslation"},
        [53655] = {"纯净审判", "使你的圣印和审判法术造成的伤害提高5%，且你的审判法术能使你的施法和近战急速提高3%，持续1分钟。\n\n效果：施法和近战速度提高3%。", "SpellTranslation", "等级 1"},
        [53656] = {"纯净审判", "使你的圣印和审判法术造成的伤害提高10%，且你的审判法术能使你的施法和近战急速提高6%，持续1分钟。\n\n效果：施法和近战速度提高6%。", "SpellTranslation", "等级 2"},
        [53657] = {"纯净审判", "使你的圣印和审判法术造成的伤害提高15%，且你的审判法术能使你的施法和近战急速提高9%，持续1分钟。\n\n效果：施法和近战速度提高9%。", "SpellTranslation", "等级 3"},
        [53659] = {"神圣净化", "你的清洁术有一定几率提高目标对疾病、魔法和中毒效果的抵抗几率。\n\n效果：疾病、魔法和毒药抗性提高30%。", "SpellTranslation"},
        [53660] = {"神佑之手", "使自由之手、牺牲之手和拯救之手的法力消耗降低15%，使拯救之手的效果提高50%，并使牺牲之手的效果额外提高5%。", "SpellTranslation", "等级 1"},
        [53661] = {"神佑之手", "使自由之手、牺牲之手和拯救之手的法力消耗降低30%，使拯救之手的效果提高100%，并使牺牲之手的效果额外提高10%。", "SpellTranslation", "等级 2"},
        [53671] = {"纯净审判", "使你的圣印和审判法术造成的伤害提高5%，且你的审判法术能使你的施法和近战急速提高3%，持续1分钟。", "SpellTranslation", "等级 1"},
        [53672] = {"圣光灌注", "你的神圣震击暴击会使下一个圣光闪现施法时间缩短 0.75 秒，或使下一个圣光术暴击几率提高 10%。此外，使你对拥有圣洁护盾的目标施放圣光闪现时，在 12 秒内额外恢复 0% 的治疗量。\n\n效果：你的下一次圣光闪现的施法时间缩短0.75。2秒，或下一次圣光术的暴击几率提高10%。", "SpellTranslation"},
