        [57564] = {"邪能智力", "使小队和团队成员的智力提高一定量，精神提高一定量。\n\n效果：智力提高，精神提高。", "SpellTranslation", "等级 2"},
        [57565] = {"邪能智力", "使小队和团队成员的智力提高一定量，精神提高一定量。\n\n效果：智力提高，精神提高。", "SpellTranslation", "等级 3"},
