        [57934] = {"嫁祸诀窍", "嫁祸诀窍的盗贼技能效果。\n\n效果：The threat caused by your next damaging attack and all actions taken for d afterwards will be transferred to the target. In addition, all damage caused by the target is increased by s1% during this time.", "SpellTranslation"},
        [57946] = {"生命分流", "将 2000 点加精神值 150% 的生命值转化为 2000 点加法术强度 50% 的法力值。法术强度会提高返还的法力值。", "SpellTranslation", "等级 8"},
        [57960] = {"水之护盾", "施法者被水之护盾环绕，每 5 秒恢复 100 点法力值。法术、近战或远程攻击命中施法者时，恢复 40 点法力值，并消耗 1 层护盾。每几秒最多触发一次，持续 10分钟。萨满同一时间只能激活一种元素护盾。\n\n效果：每5秒恢复100点法力值。对你使用的攻击和法术为你恢复400点法力值。3次充能。", "SpellTranslation", "等级 9"},
        [57992] = {"毒伤", "终结技，消耗目标身上的致命药膏层数并立即造成毒药伤害。每个连击点消耗一层，消耗层数越多伤害越高，并短暂提高你施加药膏的几率：\n1层：约75点毒药伤害，另受攻击强度加成\n2层：约150点毒药伤害，另受攻击强度加成\n3层：约225点毒药伤害，另受攻击强度加成\n4层：约300点毒药伤害，另受攻击强度加成\n5层：约375点毒药伤害，另受攻击强度加成\n\n效果：Chance to apply Deadly Poison increased by % and frequency of applying Instant Poison increased 一定量。", "SpellTranslation", "等级 3"},
