        [84664] = {"奥术强化", "激活后，你的法术伤害提高 30%，施法法力消耗提高 30%，持续 15 秒。\n\n效果：法术伤害和法力消耗提高。", "SpellTranslation"},
        [84665] = {"减速术", "使目标移动速度降低 50%，远程攻击间隔延长 -50%，施法时间延长 -50%，持续 15 秒。\n\n效果：移动速度降低一定比例。远程攻击间隔延长一定比例。施法时间延长一定比例。", "SpellTranslation"},
        [84667] = {"魔法武器", "制造一件耐久度为 50 的魔法武器，任何可以使用该类型武器的人都可以装备。武器造成的伤害取决于法师等级。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 1"},
        [84668] = {"魔法武器", "制造一件耐久度为 50 的魔法武器，任何可以使用该类型武器的人都可以装备。武器造成的伤害取决于法师等级。\n\n制造出的物品在离线超过 15 分钟后会消失。", "SpellTranslation", "等级 2"},
