        [84697] = {"Empowered Fury", "昏迷。", "SpellTranslation"},
        [84701] = {"恶魔增效", "强化术士召唤的恶魔。\n\n小鬼：法术暴击几率提高。\n\n虚空行者：生命值和威胁值提高。\n\n魅魔：解除所有昏迷和移动限制效果。\n\n地狱猎犬：攻击速度提高。\n\n恶魔卫士：攻击速度提高并免疫昏迷和移动限制效果。", "SpellTranslation"},
        [84703] = {"灵魂契约", "与一名小队或团队成员的灵魂缔结契约。若目标在契约期间死亡，你获得 1 块灵魂碎片，法术伤害提高 36 点，持续 15秒。\n\n效果：法术伤害提高 36。点。", "SpellTranslation"},
        [84704] = {"灵魂契约", "与一名小队或团队成员的灵魂缔结契约。若目标在契约期间死亡，你获得 1 块灵魂碎片，法术伤害提高 36 点，持续 15秒。\n\n效果：与附近术士灵魂相连。", "SpellTranslation"},
        [84708] = {"恶魔传送门", "撕开通往扭曲虚空的传送门，持续 15秒，周期性释放受你控制的恶魔。这些恶魔不会取代你当前激活的恶魔，最后召唤出的恶魔必定是恶魔卫士，并会使你当前目标昏迷。", "SpellTranslation"},
        [84722] = {"强化暗影撕咬", "你的地狱猎犬每次用暗影撕咬命中时恢复最大法力值的 5%。", "SpellTranslation", "等级 1"},
        [84723] = {"强化暗影撕咬", "你的地狱猎犬每次用暗影撕咬命中时恢复最大法力值的 5%。", "SpellTranslation", "等级 2"},
        [84724] = {"暗影之怒", "释放暗影之怒，造成 228 到 270 点暗影伤害，并使 8 码范围内所有敌人昏迷。", "SpellTranslation", "等级 2"},
        [84725] = {"暗影之怒", "释放暗影之怒，造成 369 到 433 点暗影伤害，并使 8 码范围内所有敌人昏迷。", "SpellTranslation", "等级 3"},
        [84728] = {"献祭光环", "地狱火周围的敌人每隔一段时间受到一定量火焰伤害。\n\n效果：每隔一段时间对附近的敌人造成一定量火焰伤害。", "SpellTranslation"},
        [84730] = {"野性攻击", "所有可装备武器都会根据武器每秒伤害获得额外野性攻击强度。只有德鲁伊可以看到此属性。", "SpellTranslation", "被动"},
