        [86617] = {"石头披风", "激活后使你融入周围的土地和岩石中，降低敌人发现你的几率。持续到取消或移动。拥有影遁能力的潜行者和德鲁伊在潜行或徘徊时更难被发现。\n\n效果：隐匿。", "SpellTranslation", "种族"},
        [86618] = {"灵魂行走", "激活后使你进入虚空形态，降低敌人发现你的几率。持续到取消或移动。拥有影遁能力的潜行者和德鲁伊在潜行或徘徊时更难被发现。\n\n效果：灵魂行走。", "SpellTranslation", "种族"},
        [86619] = {"科技迷雾", "激活后使你扭曲周围的光线，降低敌人发现你的几率。持续到取消或移动。拥有影遁能力的潜行者和德鲁伊在潜行或徘徊时更难被发现。\n\n效果：隐藏。", "SpellTranslation", "种族"},
        [86620] = {"影月遁", "激活后可遁入阴影，降低敌人发现你的几率。持续直到取消或移动为止。具有影遁的潜行者和德鲁伊在潜行或潜伏时更难被发现。\n\n效果：隐入暗影。", "SpellTranslation", "种族"},
        [86621] = {"死亡裹尸布", "激活后使你拥抱亡灵的黑暗，降低敌人发现你的几率。持续到取消或移动。拥有影遁能力的潜行者和德鲁伊在潜行或徘徊时更难被发现。\n\n效果：拥抱黑暗。", "SpellTranslation", "种族"},
